//! Cross-checks the Rust core against the web application: drawings saved by the JS app must load and re-save
//! unchanged, and the geometry queries must return what the JS implementation returned
//! (fixtures generated by `node tests/fixtures/make-fixtures.mjs`).
use cadforge_core::drawing::Drawing;
use cadforge_core::entities::*;
use cadforge_core::geom::*;
use serde_json::Value;
use std::path::PathBuf;

fn fixture(name: &str) -> String {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures")
        .join(name);
    std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
}

/// Compare JSON trees treating all numbers as f64 within `tol`.
fn json_eq(a: &Value, b: &Value, path: &str, tol: f64) -> Result<(), String> {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => {
            let (x, y) = (x.as_f64().unwrap(), y.as_f64().unwrap());
            if (x - y).abs() <= tol * 1f64.max(x.abs()) {
                Ok(())
            } else {
                Err(format!("{path}: {x} != {y}"))
            }
        }
        (Value::Object(x), Value::Object(y)) => {
            for (k, v) in x {
                match y.get(k) {
                    Some(w) => json_eq(v, w, &format!("{path}.{k}"), tol)?,
                    None if v.is_null() => {}
                    None => return Err(format!("{path}.{k}: missing in second")),
                }
            }
            for (k, v) in y {
                if !x.contains_key(k) && !v.is_null() {
                    return Err(format!("{path}.{k}: missing in first"));
                }
            }
            Ok(())
        }
        (Value::Array(x), Value::Array(y)) => {
            if x.len() != y.len() {
                return Err(format!("{path}: length {} != {}", x.len(), y.len()));
            }
            for (i, (v, w)) in x.iter().zip(y).enumerate() {
                json_eq(v, w, &format!("{path}[{i}]"), tol)?;
            }
            Ok(())
        }
        _ if a == b => Ok(()),
        _ => Err(format!("{path}: {a} != {b}")),
    }
}

#[test]
fn web_drawings_round_trip_through_the_rust_model() {
    for name in ["sample.cadforge.json", "kitchen-sink.cadforge.json"] {
        let text = fixture(name);
        let original: Value = serde_json::from_str(&text).unwrap();
        let d = Drawing::from_json_str(&text, None).unwrap_or_else(|e| panic!("{name}: {e}"));
        let back = d.to_json();
        json_eq(&original, &back, name, 1e-12).unwrap_or_else(|e| panic!("{e}"));
    }
}

fn kind_str(k: SnapType) -> &'static str {
    match k {
        SnapType::End => "END",
        SnapType::Mid => "MID",
        SnapType::Cen => "CEN",
        SnapType::Qua => "QUA",
        SnapType::Nod => "NOD",
        SnapType::Ins => "INS",
    }
}

fn close(a: f64, b: f64, what: &str) {
    assert!(
        (a - b).abs() <= 1e-6 * 1f64.max(b.abs()),
        "{what}: rust {a} vs js {b}"
    );
}

fn check(name: &str) {
    let d = Drawing::from_json_str(&fixture(&format!("{name}.cadforge.json")), None).unwrap();
    let oracle: Vec<Value> =
        serde_json::from_str(&fixture(&format!("{name}.oracle.json"))).unwrap();
    let probes = [
        pt(0.0, 0.0),
        pt(5.0, 5.0),
        pt(12.5, 3.25),
        pt(-4.0, 20.0),
        pt(31.0, 6.0),
        pt(73.0, 11.0),
    ];
    for o in &oracle {
        let id = o["id"].as_u64().unwrap();
        let e = d.by_id(id).unwrap_or_else(|| panic!("entity {id}"));
        let tag = format!("{name} #{id} {}", o["type"].as_str().unwrap());
        let b = bounds_of(e, &d);
        let ob = &o["bounds"];
        match (b, ob.is_null()) {
            (Some(b), false) => {
                close(
                    b.min_x,
                    ob["minX"].as_f64().unwrap(),
                    &format!("{tag} minX"),
                );
                close(
                    b.min_y,
                    ob["minY"].as_f64().unwrap(),
                    &format!("{tag} minY"),
                );
                close(
                    b.max_x,
                    ob["maxX"].as_f64().unwrap(),
                    &format!("{tag} maxX"),
                );
                close(
                    b.max_y,
                    ob["maxY"].as_f64().unwrap(),
                    &format!("{tag} maxY"),
                );
            }
            (None, true) => {}
            (b, _) => panic!("{tag}: bounds rust {b:?} vs js {ob}"),
        }
        if o["type"] == "viewport" {
            continue;
        }
        // segments
        let segs = segs_of(e, &d);
        assert_eq!(
            segs.len(),
            o["nsegs"].as_u64().unwrap() as usize,
            "{tag}: segment count"
        );
        for (i, (s, js)) in segs.iter().zip(o["segs"].as_array().unwrap()).enumerate() {
            let js = js.as_array().unwrap();
            let f = |k: usize| js[k].as_f64().unwrap();
            match (s, js[0].as_str().unwrap()) {
                (Seg::L { a, b, .. }, "l") => {
                    close(a.x, f(1), &format!("{tag} seg{i}.ax"));
                    close(a.y, f(2), &format!("{tag} seg{i}.ay"));
                    close(b.x, f(3), &format!("{tag} seg{i}.bx"));
                    close(b.y, f(4), &format!("{tag} seg{i}.by"));
                }
                (Seg::A { c, r, a0, sw, .. }, "a") => {
                    close(c.x, f(1), &format!("{tag} seg{i}.cx"));
                    close(c.y, f(2), &format!("{tag} seg{i}.cy"));
                    close(*r, f(3), &format!("{tag} seg{i}.r"));
                    close(*a0, f(4), &format!("{tag} seg{i}.a0"));
                    close(*sw, f(5), &format!("{tag} seg{i}.sw"));
                }
                (s, k) => panic!("{tag} seg{i}: rust {s:?} vs js kind {k}"),
            }
        }
        // pick distances
        for (p, js) in probes.iter().zip(o["pick"].as_array().unwrap()) {
            let r = pick_distance(e, *p, &d);
            match js.as_str() {
                Some("inf") => assert!(
                    r.is_infinite(),
                    "{tag}: pick at {p:?} should be infinite, got {r}"
                ),
                _ => close(
                    r,
                    js.as_f64().unwrap(),
                    &format!("{tag} pick at ({},{})", p.x, p.y),
                ),
            }
        }
        // snaps
        let snaps = snap_points_of(e, &d);
        let osn = o["snaps"].as_array().unwrap();
        assert_eq!(snaps.len(), osn.len(), "{tag}: snap count");
        for (s, js) in snaps.iter().zip(osn) {
            assert_eq!(
                kind_str(s.kind),
                js[0].as_str().unwrap(),
                "{tag}: snap kind"
            );
            close(s.pt.x, js[1].as_f64().unwrap(), &format!("{tag} snap x"));
            close(s.pt.y, js[2].as_f64().unwrap(), &format!("{tag} snap y"));
        }
        // grips
        let grips = grips_of(e, &d);
        let og = o["grips"].as_array().unwrap();
        assert_eq!(grips.len(), og.len(), "{tag}: grip count");
        for (g, js) in grips.iter().zip(og) {
            assert_eq!(
                g.id,
                js[0].as_str().unwrap_or(&js[0].to_string()),
                "{tag}: grip id"
            );
            close(g.pt.x, js[1].as_f64().unwrap(), &format!("{tag} grip x"));
            close(g.pt.y, js[2].as_f64().unwrap(), &format!("{tag} grip y"));
        }
        // explode
        let ex: Vec<String> = explode_entity(e, &d)
            .unwrap_or_default()
            .iter()
            .map(|x| x.type_name().to_string())
            .collect();
        let oex: Vec<String> = o["explode"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect();
        assert_eq!(ex, oex, "{tag}: explode result");
        // text
        let texts = texts_of(e, &d);
        let ot = o["texts"].as_array().unwrap();
        assert_eq!(texts.len(), ot.len(), "{tag}: text count");
        for (t, js) in texts.iter().zip(ot) {
            assert_eq!(t.s, js[0].as_str().unwrap(), "{tag}: text string");
            close(t.p.x, js[1].as_f64().unwrap(), &format!("{tag} text x"));
            close(t.p.y, js[2].as_f64().unwrap(), &format!("{tag} text y"));
            close(t.h, js[3].as_f64().unwrap(), &format!("{tag} text h"));
            close(t.rot, js[4].as_f64().unwrap(), &format!("{tag} text rot"));
        }
        // hatch lines
        if let Some(n) = o.get("hatch").and_then(Value::as_u64) {
            let got = hatch_segments(e, &d).map(|v| v.len()).unwrap_or(0);
            assert_eq!(got as u64, n, "{tag}: hatch line count");
        }
    }
}

#[test]
fn sample_geometry_matches_the_web_app() {
    check("sample");
}

#[test]
fn kitchen_sink_geometry_matches_the_web_app() {
    check("kitchen-sink");
}
